package dedup

// BUG: contains() linearly rescans the whole "seen" slice for every item,
// making Dedup O(n^2) overall - far too slow for large inputs with many
// duplicates.
func contains(seen []string, s string) bool {
	for _, x := range seen {
		if x == s {
			return true
		}
	}
	return false
}

// Dedup returns items with duplicates removed, keeping the FIRST
// occurrence of each value and preserving relative order.
func Dedup(items []string) []string {
	var seen []string
	var out []string
	for _, it := range items {
		if !contains(seen, it) {
			seen = append(seen, it)
			out = append(out, it)
		}
	}
	return out
}

