package dedup

import (
	"fmt"
	"testing"
	"time"
)

func TestDedupBasic(t *testing.T) {
	got := Dedup([]string{"a", "b", "a", "c", "b"})
	want := []string{"a", "b", "c"}
	if len(got) != len(want) {
		t.Fatalf("Dedup(...) = %v, want %v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("Dedup(...) = %v, want %v (order must match first occurrence)", got, want)
		}
	}
}

func TestDedupEmpty(t *testing.T) {
	if got := Dedup(nil); len(got) != 0 {
		t.Fatalf("empty input must give an empty result, got %v", got)
	}
}

func TestDedupPerformance(t *testing.T) {
	n := 100000
	items := make([]string, n)
	for i := 0; i < n; i++ {
		items[i] = fmt.Sprintf("item-%d", i%(n/2))
	}

	start := time.Now()
	got := Dedup(items)
	elapsed := time.Since(start)

	if len(got) != n/2 {
		t.Fatalf("large-input dedup count = %d, want %d", len(got), n/2)
	}
	if got[0] != "item-0" || got[1] != "item-1" {
		t.Fatalf("large-input order wrong: first two are %v", got[:2])
	}
	// calibrated: a linear contains() scan is ~2.9s on fast native
	// hardware at n=100000; a map is ~5ms
	if elapsed >= 1200*time.Millisecond {
		t.Fatalf("Dedup took %v for %d items; expected a map[string]struct{} for membership, "+
			"not a linear scan per item (O(n^2))", elapsed, n)
	}
}

