package dedup

// Dedup returns items with duplicates removed, keeping the FIRST
// occurrence of each value and preserving relative order. A map gives O(1)
// membership checks, so this runs in O(n) overall.
func Dedup(items []string) []string {
	seen := make(map[string]struct{}, len(items))
	var out []string
	for _, it := range items {
		if _, ok := seen[it]; !ok {
			seen[it] = struct{}{}
			out = append(out, it)
		}
	}
	return out
}

